/**
 * The stored object is gone — the row and the bucket have drifted apart. Raised by the
 * adapters so callers don't have to know about ENOENT or S3's NoSuchKey.
 */
export class FileNotFoundError extends Error {
  constructor(key: string) {
    super(`No stored file for key "${key}"`);
  }
}

/** Port for invoice file bytes. Keys are generated by us, never taken from user input. */
export abstract class FileStorage {
  abstract put(key: string, body: Buffer, contentType: string): Promise<void>;
  abstract get(key: string): Promise<Buffer>;
  abstract delete(key: string): Promise<void>;
}
